/* ============================================================
   PATCH v1.4.0 — Premium UI дерева гипотез
   ============================================================ */

#taskHypothesesGroup {
    background: transparent !important;
    border: none !important;
    padding: 0 !important;
}
#hypTreeRoot {
    display: flex !important;
    flex-direction: column !important;
    gap: 16px !important;
}

/* --- КАРТОЧКА ГИПОТЕЗЫ --- */
.hyp-card {
    background: var(--trk-panel-bg) !important;
    border: 1px solid var(--trk-card-border) !important;
    border-radius: 12px !important;
    box-shadow: 0 4px 20px rgba(0,0,0,0.15) !important;
    overflow: hidden !important;
    transition: border-color 0.2s, box-shadow 0.2s !important;
}
.hyp-card:hover {
    border-color: rgba(245,215,110,0.4) !important;
    box-shadow: 0 6px 24px rgba(0,0,0,0.25) !important;
}

.hyp-card > .hyp-head {
    display: flex !important;
    justify-content: space-between !important;
    align-items: center !important;
    background: var(--trk-hover-row) !important;
    padding: 12px 16px !important;
    cursor: pointer !important;
    user-select: none !important;
    list-style: none !important;
    border-bottom: 1px solid transparent !important;
}
.hyp-card[open] > .hyp-head {
    border-bottom-color: var(--trk-card-border) !important;
}
.hyp-card > .hyp-head::-webkit-details-marker { display: none !important; }

.hyp-head-left { display: flex; align-items: center; gap: 12px; overflow: hidden; }
.hyp-head-right { display: flex; align-items: center; gap: 16px; flex-shrink: 0; }

.hyp-num {
    font-size: 0.85rem !important;
    font-weight: 800 !important;
    color: var(--trk-accent) !important;
    text-transform: uppercase !important;
    letter-spacing: 0.5px !important;
    background: rgba(245,215,110,0.1) !important;
    padding: 3px 10px !important;
    border-radius: 8px !important;
}
.hyp-title-preview {
    font-size: 0.95rem !important;
    font-weight: 700 !important;
    color: var(--trk-text) !important;
    white-space: nowrap !important;
    overflow: hidden !important;
    text-overflow: ellipsis !important;
}
.hyp-progress {
    font-size: 0.75rem !important;
    font-weight: 700 !important;
    color: var(--trk-meta) !important;
}

/* --- ТЕЛО ГИПОТЕЗЫ --- */
.hyp-body {
    padding: 16px 20px !important;
    display: flex !important;
    flex-direction: column !important;
    gap: 16px !important;
    background: var(--trk-panel-bg) !important;
}

/* --- СПИСОК ЗАДАНИЙ --- */
.hyp-tasks-list {
    display: flex !important;
    flex-direction: column !important;
    gap: 12px !important;
    margin-top: 4px !important;
    padding-left: 16px !important;
    border-left: 2px dashed rgba(128,128,128,0.2) !important;
}

/* --- КАРТОЧКА ЗАДАНИЯ --- */
.hyp-task-block {
    background: rgba(0,0,0,0.15) !important;
    border: 1px solid var(--trk-border-soft) !important;
    border-left: 4px solid #3498db !important;
    border-radius: 8px !important;
    overflow: hidden !important;
}
.hyp-task-head {
    display: flex !important;
    justify-content: space-between !important;
    align-items: center !important;
    padding: 10px 14px !important;
    cursor: pointer !important;
    list-style: none !important;
    background: rgba(255,255,255,0.02) !important;
    border-bottom: 1px solid transparent !important;
}
.hyp-task-head::-webkit-details-marker { display: none !important; }
.hyp-task-block[open] .hyp-task-head { border-bottom-color: var(--trk-border-soft) !important; }

.hyp-task-head-left { display: flex; align-items: center; gap: 12px; overflow: hidden; }
.hyp-task-num {
    font-size: 0.8rem !important;
    font-weight: 800 !important;
    color: #3498db !important;
}
.hyp-task-title {
    font-size: 0.9rem !important;
    font-weight: 600 !important;
    color: var(--trk-text) !important;
    white-space: nowrap !important;
    overflow: hidden !important;
    text-overflow: ellipsis !important;
}
.hyp-task-status-icon { font-size: 1rem !important; }

/* Поля заданий и гипотез */
.hyp-fields {
    display: flex !important;
    flex-direction: column !important;
    gap: 12px !important;
    width: 100% !important;
    padding: 16px !important;
}
.hyp-fld {
    width: 100% !important;
    box-sizing: border-box !important;
    background: var(--trk-input-bg) !important;
    border: 1px solid var(--trk-input-border) !important;
    border-radius: 8px !important;
    color: var(--trk-text) !important;
    padding: 10px 14px !important;
    font-family: inherit !important;
    font-size: 0.9rem !important;
    transition: border-color 0.15s, box-shadow 0.15s !important;
}
.hyp-fld:focus {
    outline: none !important;
    border-color: var(--trk-accent) !important;
    box-shadow: 0 0 0 3px var(--trk-accent-bg) !important;
}
.hyp-title-input {
    font-weight: 700 !important;
    font-size: 1.05rem !important;
}
.hyp-desc-input {
    resize: vertical !important;
    min-height: 60px !important;
    line-height: 1.4 !important;
}

/* Строка с датами и статусами */
.hyp-meta-row {
    display: flex !important;
    flex-wrap: wrap !important;
    gap: 16px !important;
    align-items: center !important;
    justify-content: space-between !important;
}
.hyp-dates {
    display: flex !important;
    gap: 12px !important;
    align-items: center !important;
}
.hyp-dates label {
    display: flex !important;
    align-items: center !important;
    gap: 8px !important;
    font-size: 0.8rem !important;
    color: var(--trk-meta) !important;
}
.hyp-dates input[type="date"] {
    width: auto !important;
    padding: 6px 10px !important;
    margin: 0 !important;
}

/* СЕГМЕНТИРОВАННЫЙ ПЕРЕКЛЮЧАТЕЛЬ СТАТУСОВ */
.hyp-st-group {
    display: inline-flex !important;
    background: rgba(0,0,0,0.3) !important;
    padding: 4px !important;
    border-radius: 10px !important;
    border: 1px solid var(--trk-border-soft) !important;
    gap: 4px !important;
}
.hyp-st-btn {
    width: 34px !important;
    height: 34px !important;
    border-radius: 8px !important;
    border: none !important;
    background: transparent !important;
    cursor: pointer !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    font-size: 1.1rem !important;
    transition: all 0.2s !important;
    filter: grayscale(1) opacity(0.4) !important;
}
.hyp-st-btn:hover {
    filter: grayscale(0) opacity(1) !important;
    background: rgba(255,255,255,0.05) !important;
    transform: translateY(-1px) !important;
}

/* Активные цвета */
.hyp-st-btn.active { filter: none !important; box-shadow: inset 0 0 0 1px rgba(255,255,255,0.1) !important; }
.hyp-st-btn.planned.active { background: rgba(149,165,166,0.2) !important; }
.hyp-st-btn.in_progress.active { background: rgba(52,152,219,0.25) !important; }
.hyp-st-btn.done.active { background: rgba(46,204,113,0.25) !important; }
.hyp-st-btn.failed.active { background: rgba(231,76,60,0.25) !important; }

/* Кнопки */
.hyp-del-btn {
    opacity: 0.4 !important;
    font-size: 1.1rem !important;
    padding: 4px 8px !important;
    border-radius: 6px !important;
    transition: all 0.15s !important;
    background: transparent !important;
    border: none !important;
    color: var(--trk-text) !important;
    cursor: pointer !important;
}
.hyp-del-btn:hover {
    opacity: 1 !important;
    background: rgba(231,76,60,0.2) !important;
    color: #e74c3c !important;
}
.hyp-add-task {
    padding: 5px 12px !important;
    font-size: 0.75rem !important;
    border-radius: 8px !important;
    font-weight: 700 !important;
}

/* Ответственные (Спойлер) */
.hyp-people-details {
    background: rgba(0,0,0,0.2) !important;
    border: 1px solid var(--trk-border-soft) !important;
    border-radius: 8px !important;
    margin-top: 4px !important;
}
.hyp-people-details summary.hyp-people-label {
    padding: 8px 14px !important;
    font-size: 0.8rem !important;
    color: var(--trk-text) !important;
    cursor: pointer !important;
    list-style: none !important;
    display: flex !important;
    align-items: center !important;
}
.hyp-people-details summary::-webkit-details-marker { display: none !important; }
.hyp-people-details summary::before {
    content: '▶' !important;
    font-size: 0.65em !important;
    color: var(--trk-accent) !important;
    margin-right: 8px !important;
    transition: transform 0.2s !important;
    display: inline-block !important;
}
.hyp-people-details[open] summary::before { transform: rotate(90deg) !important; }
.hyp-asg-icon { opacity: 0.8; margin-right: 6px; }
.hyp-asg-names { font-weight: 600 !important; color: var(--trk-desc) !important; }
.hyp-asg-names.empty { font-weight: 400 !important; color: var(--trk-meta) !important; }
.hyp-people-count {
    background: var(--trk-accent) !important;
    color: #000 !important;
    padding: 1px 8px !important;
    border-radius: 10px !important;
    font-weight: 800 !important;
    font-size: 0.65rem !important;
    margin-left: auto !important;
}
.hyp-people-list {
    border: none !important;
    border-top: 1px solid var(--trk-border-soft) !important;
    border-radius: 0 0 8px 8px !important;
    background: transparent !important;
    padding: 10px !important;
    grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)) !important;
}

